-- 20261009_acao_cortinas_novos_tecidos (UP): insere 191 variantes de tecido AÇÃO.
-- valor_custo = preco fracionado; custo_final = valor_custo + despesas_acessorias + outras_despesas (despesas 0).
-- Nao preenche valor_venda nem fornecedor_padrao_id.
BEGIN;

CREATE TEMP TABLE _novos_tecidos AS SELECT empresa_id, nome, codigo_interno, codigo_fornecedor, nome_fornecedor, fornecedores, grupo_produto, tipo_produto, unidade_venda, linha, tipo_cortina_persiana, material_tecido, cor, largura, produto_base, variacao_cor, unidade_compra, unidade_controle, valor_custo, despesas_acessorias, outras_despesas, custo_final, grupo_tecnico, observacoes FROM produtos WHERE false;


-- Guarda: aborta se alguma variante ja existir (codigo sem zeros a esquerda ou descricao equivalente)
DO $$
DECLARE n integer;
BEGIN
  SELECT count(*) INTO n FROM _novos_tecidos t
  WHERE EXISTS (
    SELECT 1 FROM produtos p
    WHERE p.empresa_id = 1 AND (
      ltrim(coalesce(p.codigo_fornecedor,''),'0') = ltrim(t.codigo_fornecedor,'0')
      OR ltrim(coalesce(p.codigo_interno,''),'0') = ltrim(t.codigo_fornecedor,'0')
      OR ltrim(coalesce(p.codigo_barras,''),'0') = ltrim(t.codigo_fornecedor,'0')
      OR upper(regexp_replace(coalesce(p.nome,''),'[^[:alnum:]]+',' ','g')) = upper(regexp_replace(t.nome,'[^[:alnum:]]+',' ','g'))
    )
  );
  IF n > 0 THEN
    RAISE EXCEPTION 'Duplicidade: % variante(s) ja existem em produtos; carga abortada', n;
  END IF;
END $$;

SELECT empresa_id, nome, codigo_interno, codigo_fornecedor, nome_fornecedor, fornecedores, grupo_produto, tipo_produto, unidade_venda, linha, tipo_cortina_persiana, material_tecido, cor, largura, produto_base, variacao_cor, unidade_compra, unidade_controle, valor_custo, despesas_acessorias, outras_despesas, custo_final, grupo_tecnico, observacoes FROM _novos_tecidos;

DROP TABLE _novos_tecidos;

-- Conferencia: deve retornar 191
SELECT count(*) AS inseridos FROM produtos WHERE empresa_id = 1 AND observacoes LIKE 'CARGA 20261009_acao_cortinas_novos_tecidos%';

COMMIT;
